actions.script:
const L = (text) => ec.l10n.localize(text)
let shares = []
ec.message.pushErrors()
try {
    shares = Array.from(ec.resource.script('component://framework/service/org/moqui/maps/MapConfig.js').execute('liveShares', {}).locationShares || [])
} catch (err) {
    ec.logger.warn('Maps terminal: the location shares were not read: ' + (err?.message ?? err))
} finally { ec.message.clearErrors(); ec.message.popErrors() }
// an age as words, as the map's list gives it; an approximate share's position is its cell of about 1 km
const ageText = (seconds) => seconds == null ? L('No position yet') : seconds < 60 ? L('just now') : seconds < 3600
    ? Math.floor(seconds / 60) + ' ' + L('min ago') : seconds < 86400 ? Math.floor(seconds / 3600) + ' ' + L('h ago') : Math.floor(seconds / 86400) + ' ' + L('d ago')
const whom = (share) => {
    const names = Array.from(share.audience || []).map((entry) => entry.name).filter(Boolean)
    return names.length <= 2 ? names.join(', ') : names.slice(0, 2).join(', ') + ' ' + L('and') + ' ' + (names.length - 2) + ' ' + L('others')
}
const row = (share) => ({shareId: share.shareId, isOwn: share.role === 'owner',
    whoText: share.role === 'owner' ? L('You, with') + ' ' + whom(share) : share.label || share.ownerName || '',
    ageText: ageText(share.latest ? share.latest.ageSeconds : null) + (share.latest && share.latest.ageSeconds > 300 ? ' (' + L('stale') + ')' : ''),
    whereText: share.latest ? Number(share.latest.latitude).toFixed(5) + ', ' + Number(share.latest.longitude).toFixed(5)
        + (share.approximate ? ' (' + L('approximate, about 1 km') + ')' : '') : '',
    untilText: share.thruDate ? ec.l10n.format(new Date(Number(share.thruDate)), 'EEE HH:mm') : ''})
myShareList = shares.filter((share) => share.role === 'owner').map(row)
sharedShareList = shares.filter((share) => share.role !== 'owner').map(row)
